export type Merge<T> = { [K in keyof T]: T[K] } & {};
export type MergeUnion<T, Keys extends keyof T = T extends unknown ? keyof T : never> = Merge<T extends unknown ? {
    [K in Keys as K extends keyof T ? never : K]?: never;
} & {
    [K in Keys as K extends keyof T ? K : never]: T[K & keyof T];
} : never>;
export type Kinds = 'a' | 'b';
export type Param<Types> = Types | string;
export interface Resolver<A, B> { (a: A, b: B): unknown }
export interface Opts<Types, P> { Resolve: { resolve: Resolver<Types, P> } }
export interface Plain<Types, P> { z: Types; p: P }
export interface ST { k: keyof Opts<any, any>; Root: object }
export type Cfg<Types extends ST, Kind extends Kinds> = {
  [K in Kinds]: Merge<{ kind: K; o: Plain<Types, Param<Types>> & Partial<Opts<Types, Param<Types>>[Types['k']]> & MergeUnion<{ [K in keyof Opts<ST, unknown>]: Opts<ST, unknown>[K] }[keyof Opts<ST, unknown>]> }>;
}[Kind];
